PRAGMA encoding='UTF-8'; CREATE TABLE nums(n INTEGER PRIMARY KEY,w TEXT); WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<300) INSERT INTO nums SELECT x,json_extract('["","onehundred","twohundred","threehundred"]','$['||(x/100)||']')||CASE WHEN x%100<20 THEN json_extract('["","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"]','$['||(x%100)||']') ELSE json_extract('["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"]','$['||((x%100)/10)||']')||json_extract('["","one","two","three","four","five","six","seven","eight","nine"]','$['||(x%10)||']') END FROM c;